import Link from "next/link";
import crypto from "node:crypto";
import { notFound } from "next/navigation";
import { Building2, FileText, Network, ShieldCheck, Users, Globe } from "lucide-react";
import { requireViewer } from "@/lib/auth";
import { getCompanyAccess, getCompanyDirectory } from "@/lib/company";
import { SourceForm, SourceRefresh, SourceReview, type Source } from "@/components/company-sources";
import { CompanyPeople } from "@/components/company-people";
import { CompanyLogo } from "@/components/company-logo";
import { ConcernConfiguration } from "@/components/concern-forms";
import { StructureEditor } from "@/components/structure-editor";
import { StructureImport } from "@/components/structure-import";
import { PublishingPermissions, type PermissionRow } from "@/components/publishing-controls";
import { createClient } from "@/lib/supabase/server";
import { CompanyAccessForm, CompanyDocumentForm, CompanyDocumentReview, CompanyProfileForm, CompanyBulkAccess, OwnershipTransfer } from "@/components/company-forms";

const tabs = [ ["profile", "Profile", Building2], ["library", "Library", FileText], ["sources", "Sources", Globe], ["structure", "Structure", Network], ["people", "People", Users], ["access", "Access", ShieldCheck] ] as const;

export default async function CompanyPage({ searchParams }: { searchParams: Promise<{ tab?: string; invite?: string; message?: string }> }) {
  const viewer = await requireViewer(), access = await getCompanyAccess(viewer.organisationId);
  const visible = tabs.filter(([key]) => access[key === "library" ? "profile" : key] > 0);
  if (!visible.length) notFound();
  const query = await searchParams, tab = query.tab || visible[0][0];
  if (!visible.some(([key]) => key === tab)) notFound();
  const db = await createClient();
  const directory = ["structure", "people", "access"].includes(tab) ? await getCompanyDirectory(viewer.organisationId) : null;
  const sources = tab === "sources" ? await db.from("company_sources").select("id,label,url,cadence,status,checked_at").eq("organisation_id",viewer.organisationId).order("created_at") : null;
  const snapshots = tab === "sources" ? await db.from("company_source_snapshots").select("id,source_id,status,content,final_url,fetched_at").eq("organisation_id",viewer.organisationId).order("fetched_at",{ascending:false}).limit(50) : null;
  const profile = tab === "profile" ? await db.from("company_profiles").select("details,revision,updated_at").eq("organisation_id", viewer.organisationId).maybeSingle() : null;
  const documents = tab === "library" ? await db.from("company_documents").select("id,title,version,category,status,visibility,content,source_name,created_at").eq("organisation_id", viewer.organisationId).order("created_at", { ascending: false }).limit(100) : null;
  const concernRoutes = tab === "access" ? await db.from("concern_routes").select("primary_handlers,alternate_handlers,guidance").eq("organisation_id",viewer.organisationId).maybeSingle() : null;
  const grants = tab === "access" ? await db.from("company_access_grants").select("user_id,area,level").eq("organisation_id", viewer.organisationId) : null;
  const permissions = tab === "access" ? await db.from("publishing_permissions").select("*").eq("organisation_id", viewer.organisationId) : null;
  const audit = tab === "access" ? await db.from("audit_events").select("id,action,created_at,actor_id,metadata").eq("organisation_id", viewer.organisationId).like("action", "company.%").order("created_at", { ascending: false }).limit(30) : null;
  if (profile?.error || documents?.error || grants?.error || audit?.error || permissions?.error || concernRoutes?.error || sources?.error || snapshots?.error) throw new Error("Company information could not be loaded.");
  return <div className="page company-page"><header className="page-header"><div className="page-title"><span className="eyebrow">Company administration</span><h1>{viewer.organisationName}</h1></div></header><nav className="section-tabs" aria-label="Company sections">{visible.map(([key,label,Icon]) => <Link key={key} className={tab === key ? "active" : ""} aria-current={tab === key ? "page" : undefined} href={`/app/company?tab=${key}`}><Icon size={16} />{label}</Link>)}</nav>
    {tab === "sources" && <section className="company-section"><h2>Sources and developments</h2>{sources?.data?.map(s=><article className="company-document" key={s.id}><h3>{s.label}</h3><a className="text-link" href={s.url} target="_blank" rel="noopener noreferrer">{s.url}</a><p>{s.cadence} / {s.status.replaceAll("_"," ")}{s.checked_at ? ` / Checked ${new Date(s.checked_at).toLocaleString("en-GB")}` : ""}</p>{access.sources>=2&&<>{s.cadence!=="reference"&&<SourceRefresh id={s.id}/>}<details><summary>Source settings</summary><SourceForm source={s as Source}/></details></>}{snapshots?.data?.filter(v=>v.source_id===s.id).map(v=><details className="company-document" key={v.id}><summary>{new Date(v.fetched_at).toLocaleString("en-GB")} / {v.status}</summary><p className="company-document-text">{v.content}</p>{access.sources>=2&&<SourceReview id={v.id}/>}</details>)}</article>)}{!sources?.data?.length&&<p>No sources added.</p>}{access.sources>=2&&<section className="company-section"><h2>Add a source</h2><SourceForm/></section>}</section>}
    {tab === "profile" && <section className="company-section"><CompanyLogo key={profile?.data?.details?.logo_url} src={profile?.data?.details?.logo_url} name={viewer.organisationName}/><div className="section-title-row"><h2>Company profile</h2>{access.people>=2&&<Link className="button button-primary" href="/app/company?tab=people">Add users</Link>}</div><CompanyProfileForm key={profile?.data?.revision || 0} details={{company_name:viewer.organisationName,...(profile?.data?.details || {})}} revision={profile?.data?.revision || 0} editable={access.profile >= 2} /></section>}
    {tab === "library" && <><section className="company-section"><h2>Reference library</h2>{documents?.data?.length ? documents.data.map(d => <details className="company-document" key={d.id}><summary><FileText size={18} /><strong>{d.title}</strong><span className="chip">v{d.version}</span><span className={`chip ${d.status === "approved" ? "green" : ""}`}>{d.status}</span></summary><p>{d.category.replaceAll("_", " ")} / {d.visibility === "company" ? "Company members after approval" : "Library administrators only"}{d.source_name ? ` / ${d.source_name}` : ""}</p><div className="company-document-text">{d.content}</div>{access.profile >= 2 && <CompanyDocumentReview id={d.id} status={d.status} />}</details>) : <p className="empty-state">No documents added.</p>}</section>{access.profile >= 2 && <section className="company-section"><h2>Add reference document</h2><CompanyDocumentForm id={crypto.randomUUID()} /></section>}</>}
    {tab === "structure" && directory && <section className="company-section"><h2>Organisation structure</h2><div className="department-tree">{directory.departments.map(d => <article className="panel department-node" key={d.id}><div className="panel-head"><h3>{d.name}</h3></div><div className="department-head">{directory.members.find(m => m.id === d.headUserId)?.name || "Head not appointed"}</div><ul className="department-people">{directory.members.filter(m => m.department === d.key).map(m => <li key={m.id}><strong>{m.name}</strong><span>Reports to {directory.members.find(p => p.id === m.reportsTo)?.name || "not specified"}</span></li>)}</ul></article>)}</div>{!directory.departments.length && <p className="empty-state">No departments created.</p>}{access.structure >= 2 && <StructureEditor members={directory.members.filter(m => m.status === "active")} departments={directory.departments} />}</section>}
    {tab === "people" && <section className="company-section"><h2>People and invitations</h2><CompanyPeople invite={query.invite} message={query.message}/></section>}
    {tab === "structure" && directory && access.structure>=2 && <section className="company-section"><StructureImport id={crypto.randomUUID()} members={directory.members.filter(m=>m.status==="active")}/></section>}
    {tab === "access" && directory && access.access>=2 && <CompanyBulkAccess members={directory.members.filter(m=>m.status==="active"&&m.id!==viewer.id&&m.role!=="owner")}/>}
    {tab === "access" && directory && <><section className="company-section"><h2>Company administration access</h2>{viewer.role==="owner"&&<OwnershipTransfer members={directory.members.filter(m=>m.status==="active"&&m.id!==viewer.id)} companyName={viewer.organisationName}/>}<CompanyAccessForm members={directory.members.filter(m => m.role !== "owner" && m.id !== viewer.id && m.status === "active")} grants={grants?.data || []} ownAccess={access} /><PublishingPermissions members={directory.members.filter(m => m.status === "active" && m.id !== viewer.id)} rules={(permissions?.data || []) as PermissionRow[]} canEdit={access.access >= 2} /></section>{access.access >= 2 && <section className="company-section"><ConcernConfiguration members={directory.members.filter(m=>m.status==="active")} route={concernRoutes?.data||null}/></section>}<section className="company-section"><h2>Recent administration changes</h2><div className="row-list">{audit?.data?.map(e => <div className="row-item" key={e.id}><div><h3>{e.action.replace("company.", "").replaceAll("_", " ")}</h3><p>{directory.members.find(m => m.id === e.actor_id)?.name || "Administrator"}</p></div><time>{new Date(e.created_at).toLocaleString("en-GB")}</time></div>)}</div></section></>}
  </div>;
}
